            let position = point(slider.right() - px(4.), slider.center().y);
            for click_count in [1, 2] {
                let down = MouseDownEvent {
                    button: MouseButton::Left,
                    position,
                    modifiers: Default::default(),
                    click_count,
                    first_mouse: false,
