            assert!(!cx.theme().is_dark());
            assert_eq!(theme::brightness(cx), 0, "the second click moved it");
        });
        assert_eq!(
            ribbon.read_with(cx, |r, cx| r.brightness_slider(cx)),
            Some(theme::appearance_index(false, 0) as f32)
        );

