        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            assert!(window.try_find("dark-mode").is_none());
            assert!(
                window.try_find("brightness").is_some(),
                "the collapsed ribbon leaves out Brightness"
            );
        })
        .unwrap();
    }

